function cylX(x1,x2,cy,cz,r,fn){for(let x=x1;x<=x2;x++)for(let dy=-r;dy<=r;dy++)for(let dz=-r;dz<=r;dz++){if(dy*dy+dz*dz<=r*r+0.5){const t=fn?fn(x,dy,dz):'black_wool';block(x,cy+dy,cz+dz,t);}}}
function cylY(cx,cz,y1,y2,r,t){for(let y=y1;y<=y2;y++)for(let dx=-r;dx<=r;dx++)for(let dz=-r;dz<=r;dz++){if(dx*dx+dz*dz<=r*r+0.5)block(cx+dx,y,cz+dz,t);}}
function shell(x1,y1,z1,x2,y2,z2,fn){for(let x=x1;x<=x2;x++)for(let y=y1;y<=y2;y++)for(let z=z1;z<=z2;z++){if(x===x1||x===x2||y===y1||y===y2||z===z1||z===z2){block(x,y,z,fn(x,y,z));}}}
function sphere(cx,cy,cz,r,fn){for(let x=Math.floor(cx-r);x<=Math.ceil(cx+r);x++)for(let y=Math.floor(cy-r);y<=Math.ceil(cy+r);y++)for(let z=Math.floor(cz-r);z<=Math.ceil(cz+r);z++){const d=(x-cx)*(x-cx)+(y-cy)*(y-cy)+(z-cz)*(z-cz);if(d<=r*r){const t=fn?fn(x,y,z):'white_wool';if(t)block(x,y,z,t);}}}
function wheel(xc,z){for(let dx=-2;dx<=2;dx++)for(let dy=-2;dy<=2;dy++){if(dx*dx+dy*dy<=4){block(xc+dx,6+dy,z,(dx===0&&dy===0)?'gray_wool':'black_wool');}}}
